if (!validator) {
  const schema = definition.inputSchema;
  validator = this.validatorCache.get(schema);
  if (!validator) {
    validator = ajv.compile(schema);
    this.validatorCache.set(schema, validator);
  }
}

if (!validator(input)) {
  const messages = (validator.errors ?? []).map((err: any) => {
    const path = (err.instancePath as string) || 'input';
    if (err.keyword === 'required' && err.params && 'missingProperty' in err.params) {
      return `Property ${err.params.missingProperty} is required`;
    }
    if (err.keyword === 'type' && err.params && 'type' in err.params) {
      return `Property ${path} should be ${err.params.type}`;
    }
    return `Property ${path} ${err.message}`;
  });
  const result = `Invalid input: ${messages.join('; ')}`;
  return {result};
}

